import{_ as a,o as t,c as r,a5 as l}from"./chunks/framework.BF53ZjCA.js";const m=JSON.parse('{"title":"硫化物","description":"","frontmatter":{"title":"硫化物","mineralGroup":"sulfides"},"headers":[],"relativePath":"zh/classification/mineral-groups/sulfides.md","filePath":"zh/classification/mineral-groups/sulfides.md","lastUpdated":1790876393000}'),i={name:"zh/classification/mineral-groups/sulfides.md"};function s(n,e,o,d,h,c){return t(),r("div",null,[...e[0]||(e[0]=[l('<h1 id="硫化物" tabindex="-1">硫化物 <a class="header-anchor" href="#硫化物" aria-label="Permalink to &quot;硫化物&quot;">​</a></h1><h2 id="概述" tabindex="-1">概述 <a class="header-anchor" href="#概述" aria-label="Permalink to &quot;概述&quot;">​</a></h2><p>硫化物类宝石以光学效应与金属光泽著称：</p><ul><li><strong>黄铁矿</strong>：FeS₂，&quot;愚人金&quot;，立方晶系，常用于装饰品</li><li><strong>闪锌矿</strong>：ZnS，色散极高（0.156），超过钻石</li><li><strong>方铅矿</strong>：PbS，重且软（Mohs 2.5），少见作宝石</li><li><strong>辰砂（朱砂）</strong>：HgS，红色，矿物学重要</li></ul><h2 id="化学式类型" tabindex="-1">化学式类型 <a class="header-anchor" href="#化学式类型" aria-label="Permalink to &quot;化学式类型&quot;">​</a></h2><p>M_xS_y (含 S²⁻)</p><h2 id="结构" tabindex="-1">结构 <a class="header-anchor" href="#结构" aria-label="Permalink to &quot;结构&quot;">​</a></h2><p>金属阳离子与 S²⁻ 形成离子键或共价键。常见结构包括 NaCl 型 （方铅矿）、闪锌矿型（ZnS 四面体配位）、黄铁矿型（FeS₂ 哑 铃状 S₂²⁻）。</p><h2 id="代表性宝石" tabindex="-1">代表性宝石 <a class="header-anchor" href="#代表性宝石" aria-label="Permalink to &quot;代表性宝石&quot;">​</a></h2><table tabindex="0"><thead><tr><th>宝石</th><th>化学式</th><th>亚族</th></tr></thead><tbody><tr><td>Pyrite / 黄铁矿</td><td>FeS₂</td><td>pyrite</td></tr><tr><td>Sphalerite / 闪锌矿</td><td>ZnS</td><td>sphalerite</td></tr></tbody></table><p><em>详见<a href="./intro.html">矿物组总览</a>。</em></p><aside class="gem-reference-block" aria-labelledby="gem-reference-title"><p class="gem-reference-block__eyebrow">SOURCE TRACE</p><h2 id="gem-reference-title">参考依据与证据边界</h2><p class="gem-reference-block__intro">本页内容用于学习与检索；来源用于说明知识依据，不代表仅凭本页即可完成具体样品鉴定。</p><ul><li><a href="https://elearning-samples.gia.edu/Gem_Identification/Page5.html" target="_blank" rel="noreferrer">GIA：宝石的矿物种、品种与矿物组</a><span>矿物种、宝石品种与矿物组的层级关系</span><small>打开来源 ↗</small></li><li><a href="https://www.mindat.org/" target="_blank" rel="noreferrer">Mindat 矿物数据库</a><span>矿物名称、化学组成与分类检索</span><small>打开来源 ↗</small></li></ul></aside>',12)])])}const f=a(i,[["render",s]]);export{m as __pageData,f as default};
